class Solution {
public:
    int countPrimes(int n) {
        if (n < 3) return 0;
        vector<bool> prime(n, true);
        prime[0] = prime[1] = false;
        for (int p = 2; p * p < n; p++) {
            if (!prime[p]) continue;
            for (int m = p * p; m < n; m += p) prime[m] = false;
        }
        int count = 0;
        for (bool b : prime) count += b;
        return count;
    }
};
